#!/usr/bin/env python3
"""Root's explicit decisions after direct viewing of all 43 differing blind crops."""
from pathlib import Path
import csv,json
R=Path(__file__).resolve().parents[1]; stem='H156-01_156-7_scan005'
bs={x['box']:[int(x[k]) for k in ('x0','y0','x1','y1')] for x in csv.DictReader((R/'second'/f'{stem}_boxes.tsv').open(),delimiter='\t')}
cfg={'reader':'reader_c (GPT-6 Astra Pro; effort not exposed)','patches':[],'change_updates':{},'new_changes':[],'remove_doubt_places':[],'new_doubts':[],'boxes':{}}
def patch(old,new):cfg['patches'].append({'old':old,'new':new,'count':1})
markM=r'\tikz[baseline=-.4ex,x=.75em,y=.75em]{\draw (.5,.5) circle (.48);\draw (.18,.48)--(.82,.48) (.4,.2)--(.65,.8) (.32,.76)--(.72,.23);}'
markL=r'\tikz[baseline=-.4ex,x=.75em,y=.75em]{\draw (.5,.5) ellipse (.43 and .55);\draw (.3,.15)--(.3,.8) (.2,.5)--(.8,.5) (.3,.66)--(.58,.9) (.3,.45)--(.62,.18);}'
connector=r'\tikz[x=1em,y=1em]{\draw (8,1.2) .. controls (8,1) and (8,1) .. (7.7,1)--(.6,1) .. controls (.2,1) and (.2,.3) .. (0,.3);\draw (.45,.6)--(0,.3)--(.55,.28);\draw (.3,.7)--(0,.3)--(.45,.2);}'
patch(r'\textcircled{\scriptsize\unsure{e}}',markM)
patch(r'\textcircled{\scriptsize\unsure{f}}',markL)
patch(r'\deleted{\uline{\unsure{éléments}}}',r'\deleted{\uline{\unsure{éléments|points}}}')
patch(r'\deleted{\unsure{et|4}} les relations',r'\deleted{\unsure{et|4}} et les relations')
patch(r"\uline{d'inclusion de figures par strates}",r"d'\uline{inclusion de figures par strates}")
patch(r'\deleted{\unsure{F}}\Phi',r'\deleted{\unsure{F|A}}\Phi')
patch(r'\deleted{\unsure{\forall|F}}',r'\deleted{\unsure{\forall|F|\forall F}}')
patch(r'\unsure{défn|defn}',r'\unsure{dfn|défn|defn}')
patch('Cette relation induit','cette relation induit')
patch(r'\inserted{avec At~1, At~2, At~3}',r'\inserted{'+connector+r'\enspace avec At~1, At~2, At~3}')
E={
'B001':('retain; wrapper only','The visible final digit is 4 over earlier rounded strokes compatible with 3. The deleted doubt stays. Adding mspage around the excerpt supplies a wrapper already present in the page; it changes no source reading.',[]),
'B002':('replace letter with drawn mark','The circled interior contains horizontal and intersecting oblique strokes, with no separable e loop. Reproduce these strokes graphically, without assigning an alphabetic list label.',['005-A01']),
'B003':('draw label; retain remaining first reading','The circled cross/asterisk is drawn as in B002. The sign after figures is an open subset contour without a central membership bar. The opening quotation ticks remain crowded against f and doubtful; closing ticks and the three underlines remain. Empty braces after = only control spacing. The ambient script-F alphabet is governed by its first-occurrence doubt on004; no additional repeated font doubt is added.',['005-A01']),
'B004':('retain first','The text in parentheses is X incident à F: incident has its connected n-c-i-d-e-n-t strokes, and à has its accent. There is no subscript i, turnstile, ci devant or colon there. The y descender in déployement, both strates underlines and the whole tilde-F set formula stand. The first connector drawing includes the upper and lower bends and downward right boundary; alternative coordinates and line breaks describe the same geometry.',[]),
'B005':('retain first','Muni ends in an i with its dot; no separate final s follows. Both M indices are centered beneath the relations. The crossed symbol after par has a curved upper/stem-and-loop residue consistent with script F, not two clean inequality bars; retain its doubt. Script-F/font doubt is already registered at the definition. Moving math delimiters across deleted/unsure has no textual effect.',[]),
'B006':('retain first','The small crossed ambient-letter residue has a stem and curved lower stroke; it does not show a separable pair of straight inequality bars. Script F remains uncertain. Placement of dollar delimiters around the same deleted uncertain glyph is representational only.',[]),
'B007':('replace letter with drawn mark','The enclosing oval surrounds upright, crossbar and oblique strokes. No f letter can be separated securely from this crossed mark. Draw the visible strokes without imposing a letter.',['005-A02']),
'B008':('draw label and widen cancelled-word doubt','The oval crossed label is reproduced as in B007. The long strike obscures the medial letters beneath lieux; lower oval and short descending residues also permit points, alongside éléments. Its independent underline survives. The lower cancelled word has repeated short stems and dot/exit residues compatible with minimaux, so retain that doubtful candidate rather than declaring the whole word unreadable. L subset M, ens. des, insertion scope and quotation ticks remain.',['005-A02','005-A03']),
'B009':('widen doubt','The crossing covers the middle of the underlined word. The surviving lower oval and short descent permit points as well as éléments; neither is clear enough to resolve. Preserve the independent underline within the deletion.',['005-A03']),
'B011':('retain doubt','Surviving stem groups and dot/exit residues remain compatible with minimaux, although the long cancellations conceal several letters. Retain a candidate with doubt rather than replacing the entire word by illegible.',[]),
'B012':('retain first','The oval empty-set sign is crossed by an oblique slash, rather than a central vertical phi stem. The long bent connector joins this replacement definition to the L-entry correction, supporting inserted scope. Both drawings describe its two converging paths; the first includes their endpoints and bend. A margin wrapper would lose its replacement attachment.',[]),
'B013':('add live et; retain other readings','The quoted phrase reads sine qua non, with s-i-n-e and q-u-a letter groups, not rien que rien. Suivants is a continuous full word with final ts; no secure abbreviation point or separate ss/sur follows. At 1–At 3 and At 4–At 7 have single written dashes; ties and doubled TeX hyphens are typographic. The first cancellation still permits At 1 or At 4; its low return stroke belongs to the cancelling zigzag, not an independent underline. The next cancelled group permits et/4, not a clear two-lobed 3. Below it an uncancelled e loop and crossed t give live et before les relations, omitted by the first reading.',['005-A04']),
'B015':('retain; typography only','The raised phrase reads At 1 - At 3 with one horizontal dash. Ties versus spaces and - versus -- in source coding do not alter its inscription or insertion scope.',[]),
'B016':('retain; typography only','The baseline phrase reads At 4 - At 7; the numeral forms are plain. Ties/spaces and hyphen coding do not alter the single written dash.',[]),
'B017':('retain first','The cancelled group begins At and ends in overlapped digit strokes allowing 1 or 4. Its lower straight return is continuous with the cancelling zigzag; there is no separate underline to add. Neither the alternative digit nor the doubt can be removed.',[]),
'B018':('add live et; retain cancelled doubt','The upper crossed group lacks a clear double-lobed 3 and still permits et or 4. Beneath its cancellation, a separate live e loop and long t cross form et before les. The blind final 4 candidate belongs to that live short word; transcribe et without adding a digit.',['005-A04']),
'B019':('retain first','The nonempty symbol is an oval crossed obliquely, hence varnothing here. Sup has its I centered beneath it. Operatorname/subscript versus underset/roman letters and quad spacing encode the same operator, not another source sign.',[]),
'B020':('retain majorées','The middle word has initial m humps, a and the descending j, followed by the accented ending ées. It reads majorées, not propres. The underline continues through the phrase.',[]),
'B021':('retain first','The live word is est over an older ascender/loop, which remains doubtful d under deletion. Prose sup has lower-case s at body height, unlike the capital display Sup. Both complete formulas have the same F, tilde F, X, indices and inequality. Display/inline choices, operatorname versus roman Sup and spacing are representational.',[]),
'B022':('retain deletion and live est','An old ascender and loop lie beneath the live initial e. The second reading e/t describes the overlap without preserving its source state. Retain deleted doubtful d followed by live est; old strokes cannot be fully separated.',[]),
'B023':('narrow underline; retain literal C and de','The first second-letter bowl is open C without an internal G hook; the later G has that hook. De has no final s before figures. The underline begins beneath the i of inclusion, leaving preceding d and apostrophe outside it, and continues through par strates. Line breaks do not change the note.',['005-A05']),
'B024':('retain first','The mapping-like shaft has a short upright at both ends and no right oblique arrowhead. The ambient F(M) letter has a stem and two transverse bars, not a closed P bowl. Ens has no following dot, and pour contains its ou loop rather than par. The raised tilde family and its insertion are plain. Spacing/tie differences in At labels are typographic.',[]),
'B025':('retain; typography only','The underlines stop below At and do not extend to the following numerals. Tie versus ordinary space changes no reading.',[]),
'B027':('retain capital Phi','The letter has a wide oval on a central upright with a basal foot and capital extent. It is the repeated capital Phi form, not the slashed empty-set oval elsewhere. Fermés and remaining formula agree.',[]),
'B028':('retain capital Phi','Each repeated Phi has the central upright, broad oval and basal foot of the capital form. The formula and fermée remain unchanged; no independent lower-case variant is required.',[]),
'B029':('retain first','The leading cancelled family has a visible wavy tilde; it need not acquire a new doubt. The empty-set ovals have oblique slashes. In the live union the indexed and summand letters have capital-Phi stem/foot forms. The compact subscript mark still permits membership or plus and cannot be made certain. The opening parenthesis is live while et is crossed. Math-delimiter placement, displaystyle and spacing do not alter those source states.',[]),
'B030':('retain first','The first family tilde is a distinct wave above the script capital, and both empty-set signs are obliquely slashed ovals. The cancellation encloses the whole initial expression in both readings; moving dollar signs or operator spacing changes only coding.',[]),
'B032':('retain first','All three empty-set signs have diagonal slashes rather than phi uprights. The final word remains compatible with équivaut, but its thin u/t ending merges into the exit, so the uncertainty stays. The complete marginal formula and words were read.',[]),
'B033':('retain ens without point','After the terminal s of ens there is blank paper before de. There is no separate abbreviation point.',[]),
'B034':('widen old-letter doubt; retain formula','The old angular residue inside the brace permits F or A: a triangular lower outline and crossbar survive beneath live Phi. Retain F first but add A. The live letters are capital Phi; the straight line above the following ambient F is an overbar, distinct from the earlier wavy tilde. L’ens has no dot. All three quantified/member/superscript x forms remain lowercase. The later cancelled F has clear stem and two bars; the final noté symbol is capital X with a wavy tilde, not small x with a hat.',['005-A06']),
'B035':('widen cancelled-letter doubt','A lower triangular outline and transverse stroke permit an old A as well as F under the live capital Phi. The overlap prevents resolving either. Dollar delimiters add no source information.',['005-A06']),
'B036':('retain clear cancelled F','The deleted F has a distinct upright and separate top and middle bars. Cancellation strokes are separable from those identifying strokes; no renewed uncertainty is required. Added dollar delimiters are representational.',[]),
'B037':('widen cancelled-group doubt; retain rest','Before Dans, overlapped upper converging/bar strokes and lower F-shaped stem/bar may also belong to a two-symbol forall F group. Keep forall, F and forall F as alternatives. Toutes has a visible terminal curling s despite singular famille. Both empty-set signs have oblique slashes. Formula math-boundary placement changes no ink.',['005-A07']),
'B039':('widen cancelled-group doubt','The crossed upper inverted-V/bar and lower upright/bar residue cannot securely distinguish forall, F or a two-symbol forall F group. Preserve all three possibilities; math-mode wrapper is immaterial.',['005-A07']),
'B040':('retain toutes','A separate downward curling terminal s follows the e. The following singular famille does not authorize removing it or making this clear ending doubtful.',[]),
'B041':('retain first drawing','The upper end has an arrowhead directed toward b-prime; the lower unheaded end curves from a-prime. Both implementations reproduce that curved upward relation. The adjacent isolated dot has no formal punctuation place and is incidental. Coordinate/font/node wrappers do not change the source relation.',[]),
'B042':('revise abbreviation doubt; retain literal C and separate underlines','The defining label has tall d and f strokes followed by an n-like exit; no independent e/acute can be isolated, so dfn is primary with défn/defn retained as possible compressed forms. The two right-hand C letters have open bowls and no inner G hook; retain them. Figures and compatibles have two separate underlines with a gap, not one continuous rule. Math text/display wrappers and spacing are representational.',['005-A08']),
'B043':('revise abbreviation doubt','The d loop, long f and terminal n-like turn support dfn first. A compressed e or accent cannot be excluded, so défn and defn remain alternatives; the blind déf would omit the visible terminal turn. Roman/text wrappers do not add a character.',['005-A08']),
'B044':('retain C','The open bowl and simple lower exit lack the interior hook visible in the G on the left of the same equation. C is clear; no contextual G substitution or added doubt is warranted.',[]),
'B045':('retain C','The second set member repeats the open C bowl and lower terminal turn with no internal G bar. Retain the literal C. Math delimiters do not change it.',[]),
'B046':('lowercase initial and reproduce connector; retain remaining words','The first c is at body height, so change Cette to cette. De has no final s. The abbreviation has a short t cross, not the taller l ascender; retain t.f. The verb has the t-i-t sequence and u of reconstitue, not reconstruit. The added avec At 1, At 2, At 3 has a long returning connector below it, curving down at the left to the attachment before se with repeated small arrowhead strokes. Reproduce that previously omitted line; the cancelled est and all remaining wording stay. Ties are typographic.',['005-A09','005-A10']),
'B047':('retain phrase; add its connector from enclosing crop','The raised words and numerals read avec At 1, At 2, At 3; spaces versus ties are typographic. This crop also shows the long horizontal attachment line and its returning left bend, confirming the connector reproduced from B046. Count that single connector once across both boxes.',['005-A10']),
'B049':('retain first','The first glyph in the brace has two crossing diagonals, hence X, without an independent quantifier bar; it need not be doubted. There is no second X after its compatibility sign. The complete lower implication has X-prime≤X, Y-prime≤Y and X-prime compatible Y-prime, with a double-shaft right arrow. All primes and indices agree. Array/aligned, inline/display delimiters, spacing and explicit prime macros are representational differences only.',[])
}
for b,(decision,evidence,ids) in E.items():cfg['boxes'][b]={'crop':f'crops/second_scan005_{b}.png','box_coords':bs[b],'decision':decision,'evidence':evidence,'changed_place_ids':ids}
cfg['boxes']['B018']['final']=r'\deleted{\unsure{et|4}} et'
def upd(id,b,**kw):
 cfg['change_updates'][id]={'crop':f'crops/second_scan005_{b}.png','box':bs[b],**kw}
upd('S005-02-1','B002',final=markM,scan_shows=E['B002'][1],confidence='high',kind='drawing or diagram',against_C=True,against_H=True)
upd('S005-02-2','B007',final=markL,scan_shows=E['B007'][1],confidence='high',kind='drawing or diagram',against_C=True,against_H=True)
upd('S005-09','B009',final=r'\deleted{\uline{\unsure{éléments|points}}}',scan_shows=E['B009'][1],confidence='low')
upd('S005-21','B018',scan_shows='The cancelled group remains et/4; a separate uncancelled et stands below it before les. Its omission is recorded separately as S005-58.')
upd('S005-26','B023',scan_shows='De has no final s before figures. The underline begins beneath inclusion, leaving preceding d and apostrophe outside it; the scope correction is recorded separately as S005-59.')
upd('S005-42','B035',final=r'\deleted{\unsure{F|A}}\Phi',scan_shows=E['B035'][1])
upd('S005-46','B039',final=r'\deleted{\unsure{\forall|F|\forall F}}',scan_shows=E['B039'][1])
upd('S005-53','B043',final=r'\unsure{dfn|défn|defn}',scan_shows=E['B043'][1],confidence='low',against_C=True)
upd('S005-55','B046',final=r'\inserted{'+connector+r'\enspace avec At~1, At~2, At~3}',scan_shows='The raised phrase has no enclosing parentheses. A long horizontal returning connector below it turns down at the left, with small repeated arrowhead strokes toward the gap before se. Its drawing was absent from both transcriptions and is restored inside the insertion.',against_C=True)
def newrow(id,place,C,H,final,b,kind,evidence,confidence='high'):
 cfg['new_changes'].append({'id':id,'place':place,'C':C,'H':H,'final':final,'scan_shows':evidence,'confidence':confidence,'kind':kind,'crop':f'crops/second_scan005_{b}.png','box':bs[b],'against_C':True,'against_H':True,'marked_in_H':False,'consequential':False})
newrow('S005-58','axiom introduction, live word after second cancellation','omitted','omitted','et','B018','omission','A separate uncancelled e loop and long t cross lie below the crossed group, immediately before les relations. Both witnesses omit this live et.')
newrow('S005-59','At 2 margin, beginning of criterion underline',r"\uline{d'inclusion de figures par strates}",r"\emph{Critère d'inclusion des figures par strates}",r"Critère d'\uline{inclusion de figures par strates}",'B023','other','The rule begins under the i of inclusion, leaving Critère, d and apostrophe outside it. It continues through par strates; the separate de/des word difference remains S005-26.')
newrow('S005-60','paragraph following compatibility definition, first letter','Cette','Cette','cette','B046','misread word','The initial c has the height and open bowl of a lowercase body letter, unlike the larger sentence-initial D later on the same block.')
for place in ['first circled list label','second circled list label','cancelled baseline word beneath lieux','overwritten symbol under Phi inside b′) set brace','cancelled glyph before Dans in a′)','superscript label over defining equivalence']:cfg['remove_doubt_places'].append(place)
for place,reading,alts,b in [
 ('cancelled baseline word beneath lieux','éléments',['points'],'B009'),
 ('overwritten symbol under Phi inside b′) set brace','F',['A'],'B035'),
 ('cancelled glyph before Dans in a′)',r'\forall',['F',r'\forall F'],'B039'),
 ('superscript label over defining equivalence','dfn',['défn','defn'],'B043')]:cfg['new_doubts'].append({'place':place,'reading':reading,'alternatives':alts,'confidence':'low','reason':E[b][1]})
(R/'second'/f'{stem}_decisions.json').write_text(json.dumps(cfg,ensure_ascii=False,indent=2)+'\n')
print('Wrote',len(cfg['boxes']),'decisions and',len(cfg['patches']),'page patches; run apply_blind_adjudication.py 5 once.')
